-- PT120-S1-Q8. Approved 2026-10-01.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT120-S1-Q8$batch02$ AND q.stimulus=$batch02$Fortune-teller: Admittedly, the claims of some self-proclaimed “psychics” have been shown to be fraudulent, but the exposure of a few charlatans cannot alter the fundamental fact that it has not been scientifically proven that there is no such thing as extrasensory perception (ESP). Furthermore, since the failed attempts to produce such a proof have been so numerous, one must conclude that some individuals do possess ESP.$batch02$ AND q.prompt=$batch02$The reasoning in the fortune-teller's argument is most vulnerable to criticism on the grounds that the argument$batch02$ AND q.correct_choice=$batch02$E$batch02$) THEN RAISE EXCEPTION 'Question changed: PT120-S1-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch02$PT120-S1-Q8$batch02$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S1-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT120-S1-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Some individuals do possess ESP.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$No one has scientifically proven that ESP does not exist, and many attempts to prove that have failed.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Look at what the evidence actually establishes: nobody has disproven ESP. Does that prove ESP is real? Imagine a friend says, "No one has proven I *didn't* eat the last cookie, so I must have eaten it." The failure to prove something false leaves the question open. It does not settle it in favor of the claim. Many failed attempts make the open question feel weightier, but they still are not evidence that anyone actually has ESP.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the move from "not proven false" to "true."$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT120-S1-Q8$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$This is about the charlatans: exposing a few frauds does not show that everyone lacks ESP. The fortune-teller does rely on that idea, but it is a reasonable idea. Negate it and you get "proof that many lack a trait shows everyone lacks it," which is plainly false. Relying on a true principle is not the flaw.$batch02$), ($batch02$B$batch02$, $batch02$The fortune-teller does not need the number of failed attempts to be the *only* relevant factor. She treats it as enough, but she would be just as wrong if other factors mattered too.$batch02$), ($batch02$C$batch02$, $batch02$The studies she mentions are attempts to *disprove* ESP that failed. If some of them reached inaccurate conclusions, we learn nothing about the leap from "not disproven" to "proven." The flaw survives untouched.$batch02$), ($batch02$D$batch02$, $batch02$She says the attempts so far have failed, not that no scientific method could ever settle the question. Her conclusion would be just as flawed if a perfect test existed but had not yet been run.$batch02$), ($batch02$E$batch02$, $batch02$"It has not been proven that there is no ESP" becomes "some people have ESP." That treats a claim's not being shown false as proof that it is true. This is the classic unproven vs proven false flaw, run in the positive direction.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT120-S1-Q8$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
